/**
 * Verifier benchmark: every claim the demo shows, made wrong in one way at a time, and the
 * verifier's verdict on each. Generated by matchdesk.domain.verifier_benchmark; the browser
 * verifier is checked against the same cases in the studio's unit tests.
 */
import Link from "next/link";
import bench from "./generated/verifier-benchmark.json";

type Category = { id: string; label: string; truthful: boolean; total: number; correct: number; statuses: Record<string, number> };
type Example = { category: string; text: string; note: string; original: string; status: string; reason: string };
type Bench = {
  base_claims: number;
  false: { total: number; caught: number; rate: number };
  true: { total: number; wrongly_rejected: number; rate: number };
  categories: Category[];
  examples: Example[];
};

const data = bench as unknown as Bench;
const STATUS: Record<string, string> = { verified: "verified", needs_revision: "sent back", blocked: "blocked" };
const pct = (v: number) => `${(v * 100).toFixed(1)}%`;

export function VerifierBenchmark() {
  const wrong = data.categories.filter((c) => !c.truthful);
  const right = data.categories.filter((c) => c.truthful);
  const example = (id: string) => data.examples.find((e) => e.category === id);
  return (
    <>
      <div className="md-banner md-banner-info" role="note">
        <span className="md-banner-icon" aria-hidden="true">i</span>
        <span><strong>How this was built.</strong> We took each of the {data.base_claims} verified claims the overlays, recaps and stories show and made it wrong in one way at a time, the way a fluent model gets a sentence wrong. We also reworded the true claims in ways a reader would accept. The cases are generated, not hand-picked, and run on every build. They test the verifier&apos;s rules; they cannot prove there is no other way to be wrong.</span>
      </div>
      <section className="md-panel" aria-labelledby="md-bench-score">
        <h2 id="md-bench-score">Results</h2>
        <ul className="md-ae-cards">
          <li><span className="md-muted md-small">False claims caught</span><strong className="md-mono">{data.false.caught.toLocaleString("en-GB")} of {data.false.total.toLocaleString("en-GB")}</strong><span className="md-small">{pct(data.false.rate)} sent back or blocked before a producer sees them</span></li>
          <li><span className="md-muted md-small">True claims wrongly rejected</span><strong className="md-mono">{data.true.wrongly_rejected} of {data.true.total}</strong><span className="md-small">{pct(data.true.rate)} of originals and rewordings</span></li>
          <li><span className="md-muted md-small">Server and browser</span><strong className="md-mono">agree</strong><span className="md-small">on every case, checked in the unit tests</span></li>
        </ul>
        <p className="md-small">The benchmark found one real gap while it was being built: a substitution written the wrong way round (&ldquo;Barros replaced Kovac&rdquo; when Kovac replaced Barros) passed. The verifier now checks who came on and who went off, on the server and in the browser.</p>
      </section>
      <section className="md-panel" aria-labelledby="md-bench-false">
        <h2 id="md-bench-false">False claims, by kind of error</h2>
        <table className="md-table">
          <caption className="md-visually-hidden">False claims caught by the verifier, by kind of error</caption>
          <thead><tr><th scope="col">Kind of error</th><th scope="col">Caught</th><th scope="col">For example</th></tr></thead>
          <tbody>
            {wrong.map((c) => {
              const e = example(c.id);
              return (
                <tr key={c.id}>
                  <td>{c.label}</td>
                  <td className="md-mono md-bench-n">{c.correct} / {c.total}</td>
                  <td>{e ? <><q>{e.text}</q>{e.note && <> {e.note}.</>}{e.original && e.original !== e.text && <span className="md-muted md-small"> The log supports <q>{e.original}</q></span>} <span className="md-muted md-small">{STATUS[e.status] ?? e.status}: {e.reason}</span></> : "–"}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </section>
      <section className="md-panel" aria-labelledby="md-bench-true">
        <h2 id="md-bench-true">True claims, kept</h2>
        <table className="md-table">
          <caption className="md-visually-hidden">True claims and rewordings the verifier accepted</caption>
          <thead><tr><th scope="col">Kind</th><th scope="col">Verified</th></tr></thead>
          <tbody>{right.map((c) => <tr key={c.id}><td>{c.label}</td><td className="md-mono md-bench-n">{c.correct} / {c.total}</td></tr>)}</tbody>
        </table>
        <p className="md-muted md-small">
          Out of scope by design: tone and judgement (&ldquo;a dominant spell&rdquo;), which are shown as interpretation; negative sentences, which are sent back rather than checked; and Spanish and French word by word, which carry the verified claims they cite. Source: <code className="md-mono">matchdesk.domain.verifier_benchmark</code>.
        </p>
        <p className="md-small"><Link className="md-link" href="/match/nbr-riv/evidence/CL-0214">Try a claim yourself</Link></p>
      </section>
    </>
  );
}
